{
  "definition_simple": "用苛刻、残忍的方式对待他人或自己，使其受苦。",
  "definition_standard": "指以严酷、不公正的手段惩罚或为难某人，常带有虐待或折磨的意味。",
  "pos": "动词",
  "semantic_class": "action",
  "sentences": [
    {"sentence": "请不要苦待小动物。", "difficulty": "T1"},
    {"sentence": "苦待朋友会失去友谊。", "difficulty": "T1"},
    {"sentence": "他经常苦待自己的弟弟。", "difficulty": "T2"},
    {"sentence": "老师告诉我们不能苦待同学。", "difficulty": "T2"},
    {"sentence": "历史上，奴隶主苦待奴隶是很常见的。", "difficulty": "T3"},
    {"sentence": "我们应该反对任何形式的苦待。", "difficulty": "T3"},
    {"sentence": "长期苦待他人会导致严重的心理问题。", "difficulty": "T4"},
    {"sentence": "这种行为本质上是在苦待自己。", "difficulty": "T4"},
    {"sentence": "封建制度下的苦待政策引发了多次起义。", "difficulty": "T5"},
    {"sentence": "对弱势群体的系统性苦待揭示了社会结构的深层矛盾。", "difficulty": "T6"}
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {"word": "苦带", "explanation": "与'苦待'同音（kǔ dài），'带'指带子，在快速语音中可能听错。虽然'苦带'不是标准词汇，但在口语中偶尔使用。这种混淆源于同音异形。"},
    {"word": "苦袋", "explanation": "与'苦待'同音（kǔ dài），'袋'指袋子，因为发音相同，在不涉及上下文的听力测试中容易误认为'苦待'。"},
    {"word": "苦代", "explanation": "与'苦待'同音（kǔ dài），'代'指代替或时代，部分学习者可能将'苦待'误解为某种辛苦的替代行为，从而与'苦代'混淆。"}
  ],
  "primary_collocate": "百姓",
  "collocation_distractors": [
    {"word": "幸福", "explanation": "'幸福'是抽象正面的状态，与'苦待'的负面动作不协调，且'苦待幸福'无法构成合理语义搭配。"},
    {"word": "健康", "explanation": "'健康'是身体状态，'苦待健康'不符合汉语惯用法，因为'苦待'通常针对有意志的个体，而非抽象属性。"},
    {"word": "未来", "explanation": "'未来'是时间概念，'苦待未来'语义不通，'苦待'的宾语一般为人或生命体，而非抽象时间。"}
  ],
  "collocation_wrong_collocate": {
    "word": "快乐",
    "explanation": "'快乐'是积极情绪，'苦待快乐'听起来像'折磨快乐'，但实际语言中不存在这种搭配，容易让学习者误以为可以这样用。"
  },
  "cloze_distractors": [
    {"word": "时间", "reason": "填入'时间'后句子'请不要苦待时间'语义不通，因为'苦待'的对象通常是有生命的事物，而'时间'是抽象概念，不符合语义要求。"},
    {"word": "幸福", "reason": "'请不要苦待幸福'在逻辑上矛盾，'苦待'是负面行为，'幸福'是正面状态，二者不能搭配，属于语义冲突。"},
    {"word": "知识", "reason": "'请不要苦待知识'不符合常识，知识无法被'苦待'，因为'苦待'要求宾语具有感知能力，属于范畴错误。"}
  ],
  "discrimination_wrong_sentences": [
    {"sentence": "他苦待了那本书。", "reason": "错误：宾语'书'是无生命物体，'苦待'要求宾语为有生命且能感受痛苦的对象，这里犯了语义选择限制错误。"},
    {"sentence": "他苦待地跑了。", "reason": "错误：'苦待'是及物动词，不能直接加'地'修饰动词'跑'，这里错误地将'苦待'当成了副词或状态描述词，语法结构不成立。"},
    {"sentence": "苦待是一种美德。", "reason": "错误：'苦待'是负面行为，不能被评价为美德，这里犯了语用矛盾，将贬义词汇用于褒义语境。"}
  ],
  "spot_incorrect": {
    "sentence": "她总是苦待她的电脑，导致电脑经常出故障。",
    "error_description": "宾语'电脑'为无生命物体，不能成为'苦待'的合理对象，应为有生命个体（如人、动物）。",
    "corrected": "她总是苦待她的下属，导致员工经常抱怨。"
  },
  "word_family_forms": [],
  "word_family_fake_forms": [
    {"word": "苦待主义者", "explanation": "看起来像'苦待'加'主义者'形成的名词，表示主张苦待别人的人，但实际汉语中并不存在这个派生词。"},
    {"word": "苦待化", "explanation": "仿照'现代化'等后缀'化'造出的动词化形式，意为'使变得苦待'，但标准汉语中没有此词。"},
    {"word": "苦待性", "explanation": "模仿'敏感性'等名词缀'性'，表示苦待的性质或程度，但该词从未被词典收录。"}
  ],
  "syn_ant_candidates": [
    {"word": "虐待", "relation": "synonym"},
    {"word": "折磨", "relation": "synonym"},
    {"word": "苛待", "relation": "synonym"},
    {"word": "善待", "relation": "antonym"}
  ],
  "particle_candidates": []
}
